const TYPE = { video: ['video', '🎥', ['concept', 'motivate']], q: ['fun_question', '💡', ['concept', 'basic_problem']], tip: ['tip', '🧩', ['concept', 'misconception']], real: ['real_world', '🌍', ['real_world', 'summary']], game: ['game', '🎮', ['leveled_problem', 'offline_activity']], x: ['misconception', '⚠️', ['misconception', 'basic_problem']], e: ['example', '📝', ['concept', 'offline_activity']], c: ['checklist', '✅', ['next_lesson']] };
const PFX = { video: 'v', q: 'q', tip: 't', real: 'r', game: 'g', x: 'x', e: 'e', c: 'c' };
function extras(n, list) {
  const cnt = {};
  return list.map(line => {
    const p = line.split('|'); const k = p[0]; cnt[k] = (cnt[k] || 0) + 1; const [type, icon, fit] = TYPE[k];
    const id = PFX[k] + '_l' + n + '_' + cnt[k];
    if (k === 'video') return { id, type, icon, title: p[1], url: 'https://www.youtube.com/results?search_query=' + encodeURIComponent(p[2]).replace(/%20/g, '+'), description: p[3], source: '유튜브 검색 (교사 사전 확인 권장)', fit_slides: fit };
    return { id, type, icon, title: p[1], content: p[2], fit_slides: fit };
  });
}
function problemData(p, title) {
  const d = { title, scenario: { icon: p.icon, body: p.body }, question: p.q };
  if (Array.isArray(p.ci)) { d.options = p.opts.map((t, i) => (p.ci.indexOf(i) >= 0 ? { text: t, correct: true } : { text: t })); d.multi = true; d.note = '풀이: ' + p.why + ' → 알맞은 것 **' + p.ci.length + '개**'; }
  else { d.options = p.opts.map((t, i) => (i === p.ci ? { text: t, correct: true } : { text: t })); d.note = '풀이: ' + p.why + ' → **' + nm(p.opts[p.ci]) + '**'; }
  return d;
}

const LESSONS = {};
const files = Object.keys(T);
const keys = files;
files.forEach((key, idx) => {
  const t = T[key], n = idx + 1;
  const ex = extras(n, t.ex); const id = (k, i) => ex.filter(e => e.id.startsWith(PFX[k] + '_l' + n + '_'))[i - 1].id;
  const prevExit = idx === 0 ? PREV0 : T[files[idx - 1]].exit;
  const slides = [];
  const add = (block, stage, data, sug, tn) => { const sl = { id: 's' + String(slides.length + 1).padStart(2, '0'), stage, block, data }; if (tn) data.tnote = tn; sl.suggested_extras = sug || []; slides.push(sl); };
  add('cover', '도입', { title: t.cover[0], emoji: t.cover[1] }, [id('video', 1)]);
  add('review', '도입', { title: idx === 0 ? '지난 단원에서 배운 것, 기억나요?' : '지난 시간엔 무엇을 했나요?', content: t.review, items: prevExit.map(x => ({ q: x.q, a: x.a })), from: idx === 0 ? 'g5s2_science:u2_l10' : keys[idx - 1] }, [id('q', 1)]);
  add('motivate', '도입', { scene_title: t.mot.t, desc: t.mot.desc, question: t.mot.q, img: 'assets/photo/science/' + t.mot.img + '.jpg' }, [id('q', 2), id('real', 1)], t.mot.tn);
  const csug = [[id('e', 1)], [id('tip', 1)], [id('e', 2), id('tip', 2)], [id('q', 3)]];
  t.con.forEach((c, i) => add('concept', '전개', { fig: c.fig, title: c.title, content: c.content }, csug[i], c.tn));
  add('misconception', '전개', { title: '이런 생각, 맞을까요?', label: '자주 하는 생각', wrong: t.mis[0], right: t.mis[1], hint: t.mis[2] }, [id('x', 1), id('x', 2)], t.mis[3]);
  const bsug = [[id('tip', 3)], [id('e', 3)], [id('q', 4)]];
  t.basic.forEach((p, i) => add('basic_problem', '기본문제', problemData(p, '기본 문제 ' + '①②③'[i]), bsug[i]));
  add('leveled_problem', '기본문제', { title: '수준을 골라 풀어요', levels: t.lev }, [id('q', 5), id('game', 1)], t.levTn);
  add('offline_activity', '응용문제', { title: t.act.t, type: t.act.type, goal: t.act.goal, steps: t.act.steps, solo: t.act.solo, materials: t.act.mats, minutes: t.act.min }, [id('game', 2), id('tip', 4)], t.act.tn);
  add('real_world', '응용문제', { title: t.real[0], scenario: { icon: t.real[1], body: t.real[2] }, content: t.real[3] }, [id('real', 2), id('real', 3)]);
  add('advanced_problem', '응용문제', { title: '생각을 넓혀요', context: t.adv[0], challenge: t.adv[1], note: t.adv[2] }, [id('tip', 5)], t.adv[3]);
  add('exit_ticket', '정리', { title: '오늘 확인해요', items: t.exit, self: ['오늘 배운 것을 혼자 설명할 수 있어요', '조금 헷갈려요', '다시 배우고 싶어요'] }, []);
  add('summary', '정리', { title: '오늘 배운 것', points: t.sum.concat(t.story), arrows: t.arrows }, [id('real', 1)]);
  add('self_assessment', '정리', { title: '스스로 점검해요', items: ['📚 지식·이해 — ' + t.self[0], '🔧 과정·기능 — ' + t.self[1], '💛 가치·태도 — ' + t.self[2]], prompts: [t.prompt] }, [id('e', 3)]);
  add('next_lesson', '정리', { title: idx === files.length - 1 ? '이 단원을 마쳐요' : '다음 시간엔', preview: t.next, emoji: t.nextIcon }, [id('c', 1)]);
  const r = t.n.split('~').map(Number); const [a, b] = r.length === 2 ? r : [r[0], r[0]];
  LESSONS[key] = {
    meta: { grade: 5, subject: '과학', term: 2, unit: UNIT, unit_title: UT, n: a, covers: a === b ? a + '차시' : a + (b - a > 1 ? '~' : '·') + b + '차시', title: t.title, goal: t.goal.map(nm).join(' / '), std: t.std, duration_min: 40 * (b - a + 1), lesson_format: t.fmt + ' · 2세대 19장(7요소)', theme: '열 탐험 연구소', source: '2022 개정 과학 5-2 지도서 3단원(자기주도 원문 없음 — 케이티처 정본)', src_key: key },
    slides, extras: ex
  };
});

